1	import { BaseBoxShapeUtil, TLDragShapesOutInfo, TLShape, TLShapePartial } from "tldraw";
2	import { MtgCardShape, mtgCardShapeProps } from "../../shared/mtgCardShape";
3	import { CardFace, cardIndicatorPath } from "./cardRender";
4	import { handleCardClick } from "./cardTapClick";
5	import { canReceivePassenger, canRemovePassenger, handleDragShapesIn, handleDragShapesOut } from "./cardPassengers";
6	import { handleTranslateEnd } from "./cardZoneEntry";
7	import { allDraggedCardsBelongToOwner, topmostZoneAt } from "./zoneHitTest";
8	import { swallowCard } from "./cardSwallow";
9	import { lerp } from "tldraw";
10	
11	export class MtgCardShapeUtil extends BaseBoxShapeUtil<MtgCardShape> {
12	  static override type = "mtg-card" as const;
13	  static override props = mtgCardShapeProps;
14	
15	  override getDefaultProps(): MtgCardShape["props"] {
16	    return {
17	      w: 170,
18	      h: 238,
19	      instanceId: "",
20	      scryfallId: "",
21	      cardName: "",
22	      frontImageUrl: "",
23	      backImageUrl: null,
24	      face: "front",
25	      faceDown: false,
26	      tapped: false,
27	      sleeveColor: null,
28	      cardBackImageUrl: null,
29	      owner: "",
30	      isCommander: false,
31	      gameCardIndex: null,
32	    };
33	  }
34	
35	  override isAspectRatioLocked(): boolean {
36	    return true;
37	  }
38	
39	  component(shape: MtgCardShape) {
40	    return <CardFace shape={shape} />;
41	  }
42	
43	  override getIndicatorPath(shape: MtgCardShape) {
44	    return cardIndicatorPath(shape);
45	  }
46	
47	  override onClick(shape: MtgCardShape): TLShapePartial<MtgCardShape> | undefined {
48	    return handleCardClick(this.editor, shape);
49	  }
50	
51	  override canReceiveNewChildrenOfType(shape: MtgCardShape, type: TLShape["type"]): boolean {
52	    return canReceivePassenger(shape, type);
53	  }
54	
55	  override canRemoveChildrenOfType(_shape: MtgCardShape, type: TLShape["type"]): boolean {
56	    return canRemovePassenger(type);
57	  }
58	
59	  override onDragShapesIn(card: MtgCardShape, shapes: TLShape[]): void {
60	    handleDragShapesIn(this.editor, card, shapes);
61	  }
62	
63	  override onDragShapesOut(card: MtgCardShape, shapes: TLShape[], info: TLDragShapesOutInfo): void {
64	    handleDragShapesOut(this.editor, card, shapes, info);
65	  }
66	
67	  override onTranslateEnd(_initial: MtgCardShape, current: MtgCardShape): TLShapePartial<MtgCardShape> | undefined {
68	    const pointerHit = topmostZoneAt(this.editor, this.editor.inputs.currentPagePoint);
69	    if (pointerHit?.zone === "library" && allDraggedCardsBelongToOwner(this.editor, pointerHit.seatId)) {
70	      swallowCard(this.editor, current, pointerHit);
71	      return undefined;
72	    }
73	    return handleTranslateEnd(this.editor, current);
74	  }
75	
76	  override getInterpolatedProps(startShape: MtgCardShape, endShape: MtgCardShape, progress: number): MtgCardShape["props"] {
77	    return {
78	      ...endShape.props,
79	      w: lerp(startShape.props.w, endShape.props.w, progress),
80	      h: lerp(startShape.props.h, endShape.props.h, progress),
81	    };
82	  }
83	}
